{"solution_py":""""Build a canonical HTTP cache key."""
from __future__ import annotations

import json
from collections.abc import Mapping
from urllib.parse import parse_qsl, urlsplit


def canonical_cache_key(method: str, url: str, headers: Mapping[str, str]) -> str:
    """Return a stable JSON cache key for an HTTP request."""
    parsed = urlsplit(url)
    scheme = parsed.scheme.lower()
    host = (parsed.hostname or "").lower()
    port = parsed.port

    if (scheme == "http" and port == 80) or (scheme == "https" and port == 443):
        port = None

    query = tuple(
        sorted(
            (name, value)
            for name, value in parse_qsl(parsed.query, keep_blank_values=True)
            if not name.lower().startswith("utm_")
        )
    )

    varying_headers = tuple(
        sorted(
            (name.strip().lower(), value.strip())
            for name, value in headers.items()
            if name.strip().lower() in {"accept", "accept-language"}
        )
    )

    normalized = (
        method.strip().upper(),
        scheme,
        host,
        port,
        parsed.path or "/",
        query,
        varying_headers,
    )
    return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
"}
